"""Synthetic sales-rep visit notes with labels-by-construction, generated by Claude.

Why synthetic? Real CRM call notes are confidential and never public. We generate realistic notes whose
**labels are fixed before generation** (a "scenario"), and ground every scenario in real public data:
    - doctor specialty / state / segment / loyalty → sampled from our targeting table (notebook 05)
    - side-effect terms → sampled from each drug's real FAERS reaction counts (notebook 01)
    - drug and dose names → from FDA labels
The model's only job is to write a note that expresses the scenario. A human then labels a random sample
to measure how often the note really matches its intended labels (notebook 09).

Company-neutral by design: each rep is randomly assigned either the tirzepatide/orforglipron portfolio or
the semaglutide portfolio, so "competitor" is always relative to that note's rep.
"""
import json
import re

import numpy as np
import pandas as pd

from ..paths import PROCESSED, RAW, ROOT

OUT_DIR = ROOT / "data" / "04_synthetic_visit_notes"
MODEL = "claude-opus-5-5"
NOTES_PER_REQUEST = 8
SEED = 7

PORTFOLIOS = {
    "tirzepatide portfolio": {"brands": ["Mounjaro", "Zepbound", "Foundayo"],
                              "competitors": ["Ozempic", "Wegovy", "Rybelsus", "Trulicity"]},
    "semaglutide portfolio": {"brands": ["Ozempic", "Wegovy", "Rybelsus"],
                              "competitors": ["Mounjaro", "Zepbound", "Foundayo", "Trulicity"]},
}
BRAND_GENERIC = {"Mounjaro": "tirzepatide", "Zepbound": "tirzepatide", "Foundayo": "orforglipron",
                 "Ozempic": "semaglutide", "Wegovy": "semaglutide", "Rybelsus": "semaglutide",
                 "Trulicity": "dulaglutide"}
OBJECTIONS = {
    "cost_coverage":     "cost, insurance coverage or prior-authorisation hassle",
    "gi_tolerability":   "worry about nausea / GI side effects in their patients",
    "elderly_frailty":   "hesitant in older or frail patients (muscle loss, dehydration, falls)",
    "efficacy_vs_comp":  "thinks the competitor works as well or better",
    "injection_aversion": "patients dislike injections / prefer pills",
    "supply_access":     "pharmacy stock-outs or access problems",
    "safety_other":      "a specific safety question (pancreatitis, thyroid, eye/NAION, mood)",
}
INTEREST = ["high", "medium", "low"]
GI_TERMS = ["nausea", "vomiting", "diarrhoea", "constipation", "abdominal pain"]
SAFETY_TERMS = ["pancreatitis", "thyroid tumours", "vision loss", "depression", "gallbladder problems"]
AE_MODES = {
    "none":     "no side effects are mentioned at all",
    "reported": "the doctor reports that a SPECIFIC patient experienced the given side effect on the given drug",
    "negated":  "the doctor explicitly says patients did NOT have the given side effect (e.g. 'no GI issues')",
    "concern":  "the doctor worries about the side effect in general; no specific patient had it",
}
STYLES = ["terse bullet points with CRM abbreviations (pt, f/u, PA, GI, HCP, w/)",
          "short narrative, 2-4 sentences", "detailed narrative, 4-6 sentences", "rushed note with one or two typos"]

SYSTEM = """You write realistic, fictional CRM call notes that pharmaceutical sales representatives type after visiting a US doctor in 2026. They are for an open research dataset, clearly labelled synthetic.

Context you can use: oral orforglipron (Foundayo) was FDA-approved in April 2026; the Medicare GLP-1 Bridge has covered Wegovy, Zepbound and Foundayo for weight loss at $50/month since July 2026 (prior authorisation required).

Rules for every note:
- Write as the rep, in the given style and approximate length. Never use names of real people; refer to "Dr." without a surname, or to the office staff by role.
- Express EVERY label in the scenario faithfully and unambiguously (a reader should be able to recover each label from the note alone), but naturally, the way reps actually write.
- interest_level is conveyed implicitly (what the doctor says or agrees to), never as the words "interest level".
- Objections listed must appear; no other objections. Competitor brands listed must be mentioned by name; no other competitors.
- Side effects follow ae_mode exactly. Only mention the given side-effect term for reported / negated / concern; mention no side effects for none.
- The rep's own statements stay consistent with approved labelling (no off-label promotion). If the doctor asks about something off-label, the rep notes a referral to Medical Information/MSL.

Entities: list every mention in the note of a drug (brand or generic, label DRUG), a dose (e.g. "5 mg", "2.4mg", label DOSE) and a side effect or symptom term (label ADVERSE_EVENT, including negated ones). Each entity "text" must be copied EXACTLY as it appears in the note (same case and spelling), once per distinct string."""

SCHEMA = {
    "type": "object",
    "properties": {"notes": {"type": "array", "items": {
        "type": "object",
        "properties": {
            "scenario_id": {"type": "string"},
            "note": {"type": "string"},
            "entities": {"type": "array", "items": {
                "type": "object",
                "properties": {"text": {"type": "string"},
                               "label": {"type": "string", "enum": ["DRUG", "DOSE", "ADVERSE_EVENT"]}},
                "required": ["text", "label"], "additionalProperties": False}},
        },
        "required": ["scenario_id", "note", "entities"], "additionalProperties": False}}},
    "required": ["notes"], "additionalProperties": False,
}


def _faers_terms() -> dict[str, tuple[list[str], np.ndarray]]:
    """Per molecule: top FAERS reaction terms and sampling weights (real reporting frequencies)."""
    f = pd.read_csv(RAW / "fda_faers_side_effect_reports/faers_counts_glp1.csv")
    skip = r"DOSE|OFF LABEL|INEFFECTIVE|PRODUCT|WRONG|EXPIRED|NO ADVERSE|DEVICE|INAPPROPRIATE|UNDERDOSE|ADMINISTRATION"
    out = {}
    for drug, g in f[f["count_type"] == "reactions"].groupby("drug"):
        g = g[~g["term"].str.contains(skip)].nlargest(25, "count")
        out[drug] = (g["term"].str.lower().tolist(), (g["count"] / g["count"].sum()).to_numpy())
    return out


def sample_scenarios(n: int, seed: int = SEED) -> pd.DataFrame:
    """Draw n labelled scenarios grounded in the targeting table and FAERS."""
    rng = np.random.default_rng(seed)
    doctors = pd.read_parquet(PROCESSED / "targeting_scores.parquet",
                              columns=["specialty", "state", "segment", "tirzepatide_share", "rybelsus_claims"])
    doctors = doctors[~doctors["segment"].str.startswith("F")]          # reps rarely visit low-volume doctors
    faers = _faers_terms()
    rows = []
    for i in range(n):
        d = doctors.iloc[rng.integers(len(doctors))]
        portfolio = rng.choice(list(PORTFOLIOS))
        p = PORTFOLIOS[portfolio]
        discussed = list(rng.choice(p["brands"], size=rng.integers(1, 3), replace=False))
        n_comp = rng.choice([0, 1, 2], p=[0.45, 0.4, 0.15])
        competitors = list(rng.choice(p["competitors"], size=n_comp, replace=False))
        n_obj = rng.choice([0, 1, 2], p=[0.3, 0.5, 0.2])
        objections = list(rng.choice(list(OBJECTIONS), size=n_obj, replace=False))
        ae_mode = rng.choice(list(AE_MODES), p=[0.45, 0.25, 0.15, 0.15])
        ae_drug = rng.choice(discussed + competitors)
        terms, w = faers[BRAND_GENERIC[ae_drug]] if BRAND_GENERIC[ae_drug] in faers else faers["tirzepatide"]
        ae_term = rng.choice(terms, p=w) if ae_mode != "none" else ""
        # ── Consistency rules: labels must not contradict each other ────────
        if "efficacy_vs_comp" in objections and not competitors:
            competitors = [rng.choice(p["competitors"])]
        if "gi_tolerability" in objections and ae_mode in ("none", "negated"):
            ae_mode, ae_term = "concern", rng.choice(GI_TERMS)
        elif "safety_other" in objections and ae_mode == "none":
            ae_mode, ae_term = "concern", rng.choice(SAFETY_TERMS)
        rows.append({
            "scenario_id": f"s{i:05d}",
            "specialty": d["specialty"], "state": d["state"], "segment": d["segment"],
            "rep_portfolio": portfolio, "products_discussed": discussed, "competitor_mentions": competitors,
            "objections": objections, "interest_level": rng.choice(INTEREST, p=[0.3, 0.45, 0.25]),
            "ae_mode": ae_mode, "ae_term": ae_term, "ae_drug": ae_drug if ae_mode != "none" else "",
            "style": rng.choice(STYLES), "target_words": int(rng.integers(35, 130)),
        })
    return pd.DataFrame(rows)


def scenario_prompt(batch: pd.DataFrame) -> str:
    """User message: the scenarios to write, as compact JSON."""
    items = []
    for r in batch.itertuples():
        items.append({
            "scenario_id": r.scenario_id, "doctor": f"{r.specialty} in {r.state}", "rep_portfolio": r.rep_portfolio,
            "products_discussed": r.products_discussed, "competitor_mentions": r.competitor_mentions,
            "objections": [OBJECTIONS[o] for o in r.objections], "interest_level": r.interest_level,
            "ae_mode": f"{r.ae_mode}: {AE_MODES[r.ae_mode]}",
            **({"side_effect": r.ae_term, "side_effect_drug": r.ae_drug} if r.ae_mode != "none" else {}),
            "style": r.style, "approx_words": r.target_words,
        })
    return ("Write one visit note per scenario below, in the same order, and return them with their scenario_id.\n\n"
            + json.dumps(items, separators=(",", ":")))


def request_params(batch: pd.DataFrame) -> dict:
    """Messages API parameters for one request (used for both the live pilot and the Batch API)."""
    return {
        "model": MODEL,
        "max_tokens": 16000,
        "system": [{"type": "text", "text": SYSTEM, "cache_control": {"type": "ephemeral"}}],
        "output_config": {"effort": "low", "format": {"type": "json_schema", "schema": SCHEMA}},
        "messages": [{"role": "user", "content": scenario_prompt(batch)}],
    }


# ── Open-model generation (free): the model writes only the note text ───────────
OPEN_MODEL = "Qwen/Qwen2.5-7B-Instruct"
SCENARIO_FILE = OUT_DIR / "scenarios_v1.jsonl"
PROMPT_FILE = OUT_DIR / "prompt_v1.json"

OPEN_SYSTEM = ("You are a pharmaceutical sales rep typing a quick CRM call note right after visiting a doctor in 2026. "
               "Write ONLY the note, in plain everyday rep language (abbreviations are fine). "
               "Refer to the doctor only as 'Dr.' or 'HCP', never with a surname, and invent no other names. "
               "Never use headings or label words such as 'Attitude', 'Interest', 'Objection', 'Side effects' or "
               "'Competitors', and never mention the word count. Show the doctor's attitude through what they said "
               "or agreed to. Mention every product and competitor named in the brief, by name, spelled correctly "
               "(if the style asks for typos, put them in ordinary words only).")
FEW_SHOT = [
    ("Doctor: Endocrinology. Discussed: Mounjaro. Competitor: Ozempic. Doctor worries: cost, insurance coverage or "
     "prior-authorisation hassle. Attitude: positive, ready to prescribe. Side effect: one specific patient had nausea "
     "on Mounjaro. Style: short narrative. Length: about 70 words.",
     "Saw Dr. at the clinic, good convo re Mounjaro. Likes the A1c data and plans to start 2 new pts next week. "
     "Main pushback is PA hassle w/ commercial plans, asked for the coverage sheet. Still has most pts on Ozempic "
     "out of habit. Mentioned one pt had nausea on Mounjaro 5 mg the first month, settled after. F/u in 2 wks with PA support info."),
    ("Doctor: Family Practice. Discussed: Wegovy. Competitor: none. Doctor worries: none. Attitude: not interested. "
     "Side effect: doctor says patients did NOT have vomiting. Style: terse bullet points. Length: about 45 words.",
     "- Quick drop-in, HCP busy\n- Showed Wegovy Bridge info for Medicare pts\n- Doc: pts on it so far no vomiting, "
     "but weight mgmt not a priority right now\n- Left leave-behind, try again next quarter"),
]
ATTITUDE = {"high": "positive, ready to prescribe", "medium": "open but undecided", "low": "not interested"}


def brief(r) -> str:
    """Short natural-language brief for one scenario (what the small/medium open model reads)."""
    ae = {"none": "none",
          "reported": f"one specific patient had {r.ae_term} on {r.ae_drug}",
          "negated": f"doctor says patients did NOT have {r.ae_term}",
          "concern": f"doctor worries about {r.ae_term} in general (no specific patient)"}[r.ae_mode]
    return (f"Doctor: {r.specialty}. Discussed: {', '.join(r.products_discussed)}. "
            f"Competitor: {', '.join(r.competitor_mentions) or 'none'}. "
            f"Doctor worries: {'; '.join(OBJECTIONS[o] for o in r.objections) or 'none'}. "
            f"Attitude: {ATTITUDE[r.interest_level]}. Side effect: {ae}. Style: {r.style}. "
            f"Length: about {r.target_words} words.")


def chat_messages(r) -> list[dict]:
    msgs = [{"role": "system", "content": OPEN_SYSTEM}]
    for user, assistant in FEW_SHOT:
        msgs += [{"role": "user", "content": user}, {"role": "assistant", "content": assistant}]
    return msgs + [{"role": "user", "content": brief(r)}]


def export_for_colab(n: int = 1200) -> pd.DataFrame:
    """Scenarios (+ each one's brief) as JSONL and the shared prompt (system + few-shot) as JSON, for Colab."""
    sc = sample_scenarios(n)
    sc["brief"] = [brief(r) for r in sc.itertuples()]
    SCENARIO_FILE.parent.mkdir(parents=True, exist_ok=True)
    sc.to_json(SCENARIO_FILE, orient="records", lines=True, force_ascii=False)
    PROMPT_FILE.write_text(json.dumps({"model": OPEN_MODEL, "system": OPEN_SYSTEM,
                                       "few_shot": [{"user": u, "assistant": a} for u, a in FEW_SHOT]}, indent=1))
    return sc


def spans(note: str, entities: list[dict]) -> tuple[list[dict], int]:
    """Character spans for every occurrence of each entity string; returns (spans, n_entities_not_found)."""
    out, missing = [], 0
    for e in entities:
        hits = [m.start() for m in re.finditer(re.escape(e["text"]), note)] if e["text"] else []
        if not hits:
            missing += 1
        out += [{"start": s, "end": s + len(e["text"]), "text": e["text"], "label": e["label"]} for s in hits]
    out = sorted({(s["start"], s["end"], s["label"]): s for s in out}.values(), key=lambda s: s["start"])
    return out, missing
